create or replace function public.s1_assert_teacher(p_room_code text, p_teacher_token text)
returns void
language plpgsql
security definer
set search_path = public
as $$
begin
  if not exists (
    select 1
    from public.s1_rooms
    where room_code = upper(trim(p_room_code))
      and teacher_token_hash = public.s1_hash_token(p_teacher_token)
  ) then
    raise exception 'Invalid teacher token for this room.';
  end if;
end;
$$;

create or replace function public.s1_create_room(
  p_room_code text,
  p_teacher_token text,
  p_gitte_join_code text,
  p_anna_join_code text,
  p_linda_join_code text
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_room_code text := upper(trim(p_room_code));
begin
  if v_room_code = '' or trim(coalesce(p_teacher_token, '')) = '' then
    raise exception 'Room code and teacher token are required.';
  end if;

  if trim(coalesce(p_gitte_join_code, '')) = ''
     or trim(coalesce(p_anna_join_code, '')) = ''
     or trim(coalesce(p_linda_join_code, '')) = '' then
    raise exception 'All three join codes are required.';
  end if;

  if public.s1_hash_token(p_gitte_join_code) = public.s1_hash_token(p_anna_join_code)
     or public.s1_hash_token(p_gitte_join_code) = public.s1_hash_token(p_linda_join_code)
     or public.s1_hash_token(p_anna_join_code) = public.s1_hash_token(p_linda_join_code) then
    raise exception 'Join codes must be mutually distinct.';
  end if;

  if exists (select 1 from public.s1_rooms where room_code = v_room_code) then
    raise exception 'Room already exists. Use Watch room with the existing teacher token, or use a future teacher-authenticated reinitialize action.';
  end if;

  insert into public.s1_rooms(room_code, teacher_token_hash)
  values (v_room_code, public.s1_hash_token(p_teacher_token));

  insert into public.s1_room_state(room_code, current_scene, phase)
  values (v_room_code, 1, 'collecting');

  insert into public.s1_room_players(room_code, role_slot, display_name, join_code_hash)
  values
    (v_room_code, 'GAL-A', 'Gitte', public.s1_hash_token(p_gitte_join_code)),
    (v_room_code, 'GAL-B', 'Anna', public.s1_hash_token(p_anna_join_code)),
    (v_room_code, 'GAL-C', 'Linda', public.s1_hash_token(p_linda_join_code));

  insert into public.s1_game_events(room_code, event_type, details)
  values (v_room_code, 'room_created', '{}'::jsonb);

  return jsonb_build_object('room_code', v_room_code, 'ok', true);
end;
$$;

create or replace function public.s1_join_player(p_room_code text, p_join_code text)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_room_code text := upper(trim(p_room_code));
  v_player public.s1_room_players%rowtype;
  v_token text := gen_random_uuid()::text;
begin
  if v_room_code = '' or trim(coalesce(p_join_code, '')) = '' then
    raise exception 'Room code and join code are required.';
  end if;

  select *
  into v_player
  from public.s1_room_players
  where room_code = v_room_code
    and join_code_hash = public.s1_hash_token(p_join_code)
  for update;

  if not found then
    raise exception 'Invalid room code or join code.';
  end if;

  if v_player.session_token_hash is not null then
    raise exception 'This role is already claimed. Reopen the original browser session, or ask the teacher to release this player session.';
  end if;

  update public.s1_room_players
  set session_token_hash = public.s1_hash_token(v_token),
      joined_at = coalesce(joined_at, now()),
      last_seen_at = now()
  where player_id = v_player.player_id;

  insert into public.s1_game_events(room_code, event_type, actor_player_id, details)
  values (v_room_code, 'player_joined', v_player.player_id, jsonb_build_object('role_slot', v_player.role_slot));

  return jsonb_build_object(
    'room_code', v_room_code,
    'player_id', v_player.player_id,
    'role_slot', v_player.role_slot,
    'display_name', v_player.display_name,
    'session_token', v_token
  );
end;
$$;

create or replace function public.s1_get_player_by_session(p_room_code text, p_session_token text)
returns public.s1_room_players
language plpgsql
security definer
set search_path = public
as $$
declare
  v_player public.s1_room_players%rowtype;
begin
  select *
  into v_player
  from public.s1_room_players
  where room_code = upper(trim(p_room_code))
    and session_token_hash = public.s1_hash_token(p_session_token);

  if not found then
    raise exception 'Invalid or expired player session.';
  end if;

  update public.s1_room_players
  set last_seen_at = now()
  where player_id = v_player.player_id;

  return v_player;
end;
$$;

create or replace function public.s1_submit_private_choice(
  p_room_code text,
  p_session_token text,
  p_choice_id text,
  p_choice_label text
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_room_code text := upper(trim(p_room_code));
  v_player public.s1_room_players%rowtype;
  v_state public.s1_room_state%rowtype;
  v_submitted_count integer;
  v_choice_label text;
begin
  v_player := public.s1_get_player_by_session(v_room_code, p_session_token);

  select *
  into v_state
  from public.s1_room_state
  where room_code = v_room_code
  for update;

  if v_state.phase <> 'collecting' then
    raise exception 'This scene is no longer accepting private choices.';
  end if;

  select choice_label
  into v_choice_label
  from public.s1_scene_choices
  where scene_id = v_state.current_scene
    and choice_id = p_choice_id
    and active = true;

  if not found then
    raise exception 'Invalid choice for the current scene.';
  end if;

  insert into public.s1_player_decisions(room_code, scene_id, player_id, decision_type, choice_id, choice_label)
  values (v_room_code, v_state.current_scene, v_player.player_id, 'private_choice', p_choice_id, v_choice_label);

  insert into public.s1_game_events(room_code, event_type, actor_player_id, details)
  values (v_room_code, 'private_choice_locked', v_player.player_id, jsonb_build_object('scene_id', v_state.current_scene));

  select count(*)
  into v_submitted_count
  from public.s1_player_decisions
  where room_code = v_room_code
    and scene_id = v_state.current_scene
    and decision_type = 'private_choice';

  if v_submitted_count >= 3 then
    update public.s1_room_state
    set phase = 'revealed',
        updated_at = now()
    where room_code = v_room_code;

    insert into public.s1_game_events(room_code, event_type, details)
    values (v_room_code, 'scene_revealed', jsonb_build_object('scene_id', v_state.current_scene));
  end if;

  perform public.s1_touch_room(v_room_code);

  return jsonb_build_object('ok', true, 'submitted_count', v_submitted_count);
exception
  when unique_violation then
    raise exception 'Your first choice for this scene is already locked.';
end;
$$;

create or replace function public.s1_get_teacher_state(p_room_code text, p_teacher_token text)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_room_code text := upper(trim(p_room_code));
  v_state public.s1_room_state%rowtype;
  v_players jsonb;
  v_decisions jsonb;
begin
  perform public.s1_assert_teacher(v_room_code, p_teacher_token);

  select *
  into v_state
  from public.s1_room_state
  where room_code = v_room_code;

  select coalesce(jsonb_agg(jsonb_build_object(
    'player_id', player_id,
    'role_slot', role_slot,
    'display_name', display_name,
    'joined', joined_at is not null,
    'last_seen_at', last_seen_at
  ) order by role_slot), '[]'::jsonb)
  into v_players
  from public.s1_room_players
  where room_code = v_room_code;

  if v_state.phase in ('revealed','completed') then
    select coalesce(jsonb_agg(jsonb_build_object(
      'player_id', player_id,
      'choice_id', choice_id,
      'choice_label', choice_label,
      'locked_at', locked_at
    )), '[]'::jsonb)
    into v_decisions
    from public.s1_player_decisions
    where room_code = v_room_code
      and scene_id = v_state.current_scene
      and decision_type = 'private_choice';
  else
    select coalesce(jsonb_agg(jsonb_build_object(
      'player_id', player_id,
      'locked_at', locked_at
    )), '[]'::jsonb)
    into v_decisions
    from public.s1_player_decisions
    where room_code = v_room_code
      and scene_id = v_state.current_scene
      and decision_type = 'private_choice';
  end if;

  return jsonb_build_object(
    'room_code', v_room_code,
    'current_scene', v_state.current_scene,
    'phase', v_state.phase,
    'players', v_players,
    'decisions', v_decisions
  );
end;
$$;

create or replace function public.s1_advance_scene(p_room_code text, p_teacher_token text)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_room_code text := upper(trim(p_room_code));
  v_state public.s1_room_state%rowtype;
begin
  perform public.s1_assert_teacher(v_room_code, p_teacher_token);

  select *
  into v_state
  from public.s1_room_state
  where room_code = v_room_code
  for update;

  if v_state.phase <> 'revealed' then
    raise exception 'Scene can only advance after reveal. Emergency override is intentionally not part of Sprint 1.';
  end if;

  if v_state.current_scene >= 2 then
    update public.s1_room_state
    set phase = 'completed',
        updated_at = now()
    where room_code = v_room_code;
  else
    update public.s1_room_state
    set current_scene = current_scene + 1,
        phase = 'collecting',
        updated_at = now()
    where room_code = v_room_code;
  end if;

  insert into public.s1_game_events(room_code, event_type, details)
  values (v_room_code, 'teacher_advanced_scene', jsonb_build_object('from_scene', v_state.current_scene));

  return jsonb_build_object('ok', true);
end;
$$;

create or replace function public.s1_release_player_session(p_room_code text, p_teacher_token text, p_role_slot text)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_room_code text := upper(trim(p_room_code));
  v_role_slot text := upper(trim(p_role_slot));
  v_player_id uuid;
begin
  perform public.s1_assert_teacher(v_room_code, p_teacher_token);

  if v_role_slot not in ('GAL-A','GAL-B','GAL-C') then
    raise exception 'Invalid role slot.';
  end if;

  select player_id
  into v_player_id
  from public.s1_room_players
  where room_code = v_room_code
    and role_slot = v_role_slot;

  if not found then
    raise exception 'Player slot not found.';
  end if;

  update public.s1_room_players
  set session_token_hash = null,
      joined_at = null,
      last_seen_at = null
  where player_id = v_player_id;

  insert into public.s1_game_events(room_code, event_type, actor_player_id, details)
  values (v_room_code, 'teacher_released_player_session', v_player_id, jsonb_build_object('role_slot', v_role_slot));

  return jsonb_build_object('ok', true, 'role_slot', v_role_slot);
end;
$$;

create or replace function public.s1_reset_room(p_room_code text, p_teacher_token text)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_room_code text := upper(trim(p_room_code));
begin
  perform public.s1_assert_teacher(v_room_code, p_teacher_token);

  delete from public.s1_player_decisions where room_code = v_room_code;
  update public.s1_room_state
  set current_scene = 1,
      phase = 'collecting',
      updated_at = now()
  where room_code = v_room_code;

  insert into public.s1_game_events(room_code, event_type, details)
  values (v_room_code, 'teacher_reset_room', '{}'::jsonb);

  return jsonb_build_object('ok', true);
end;
$$;

create or replace function public.s2_protect_run_identity()
returns trigger
language plpgsql
set search_path = public
as $$
begin
  if new.run_id <> old.run_id
     or new.room_code <> old.room_code
     or new.run_started_at <> old.run_started_at
     or new.run_mode <> old.run_mode
     or new.behavior_dataset_eligible <> old.behavior_dataset_eligible then
    raise exception 'Formal run identity and mode cannot change after run start.';
  end if;
  return new;
end;
$$;

create or replace function public.s2_start_run(
  p_room_code text,
  p_teacher_token text,
  p_run_mode text
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_room_code text := upper(trim(p_room_code));
  v_mode text := lower(trim(coalesce(p_run_mode, '')));
  v_run public.game_runs%rowtype;
  v_joined integer;
begin
  perform public.s1_assert_teacher(v_room_code, p_teacher_token);

  if v_mode not in ('normal', 'audit') then
    raise exception 'Run mode must be NORMAL or AUDIT.';
  end if;

  perform 1 from public.s1_rooms where room_code = v_room_code for update;

  if exists (
    select 1 from public.game_runs
    where room_code = v_room_code and status = 'active'
  ) then
    raise exception 'This room already has an active formal run. Reconnect to it instead of changing its run mode.';
  end if;

  select count(*) into v_joined
  from public.s1_room_players
  where room_code = v_room_code and session_token_hash is not null;

  if v_joined <> 3 then
    raise exception 'All three assigned players must join before starting a formal run.';
  end if;

  insert into public.game_runs(
    room_code, run_mode, behavior_dataset_eligible
  ) values (
    v_room_code, v_mode, v_mode = 'normal'
  ) returning * into v_run;

  perform public.s2_log_event(
    v_run.run_id, v_room_code, null, 'run_started', null,
    jsonb_build_object(
      'run_mode', v_run.run_mode,
      'behavior_dataset_eligible', v_run.behavior_dataset_eligible
    )
  );

  return jsonb_build_object(
    'run_id', v_run.run_id,
    'run_started_at', v_run.run_started_at,
    'run_mode', v_run.run_mode,
    'behavior_dataset_eligible', v_run.behavior_dataset_eligible
  );
end;
$$;

create or replace function public.s2_open_vote(
  p_room_code text,
  p_teacher_token text
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_room_code text := upper(trim(p_room_code));
  v_run public.game_runs%rowtype;
  v_session public.discussion_sessions%rowtype;
begin
  perform public.s1_assert_teacher(v_room_code, p_teacher_token);
  v_run := public.s2_get_active_run(v_room_code);
  if v_run.run_id is null then raise exception 'No active formal run.'; end if;

  select * into v_session
  from public.discussion_sessions
  where run_id = v_run.run_id
  order by vote_round desc
  limit 1
  for update;

  if not found or v_session.status <> 'discussion' then
    raise exception 'There is no discussion currently ready to open voting.';
  end if;
  if not v_session.require_final_vote then
    raise exception 'This discussion is configured without a final vote.';
  end if;

  update public.discussion_sessions
  set status = 'voting',
      phase_deadline = now() + make_interval(secs => v_session.vote_time_limit_sec)
  where discussion_session_id = v_session.discussion_session_id
  returning * into v_session;

  perform public.s2_log_event(
    v_run.run_id, v_room_code, v_session.discussion_session_id,
    'vote_opened_by_teacher', null,
    jsonb_build_object('vote_round', v_session.vote_round)
  );

  return jsonb_build_object(
    'discussion_session_id', v_session.discussion_session_id,
    'status', v_session.status,
    'phase_deadline', v_session.phase_deadline
  );
end;
$$;

create or replace function public.s2_add_time(
  p_room_code text,
  p_teacher_token text,
  p_seconds integer
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_room_code text := upper(trim(p_room_code));
  v_run public.game_runs%rowtype;
  v_session public.discussion_sessions%rowtype;
begin
  perform public.s1_assert_teacher(v_room_code, p_teacher_token);
  if p_seconds not between 1 and 600 then
    raise exception 'Added time must be between 1 and 600 seconds.';
  end if;

  v_run := public.s2_get_active_run(v_room_code);
  if v_run.run_id is null then raise exception 'No active formal run.'; end if;

  select * into v_session
  from public.discussion_sessions
  where run_id = v_run.run_id
  order by vote_round desc
  limit 1
  for update;

  if not found or v_session.status not in ('discussion', 'voting', 'waiting_for_missing_player') then
    raise exception 'There is no open discussion or vote to extend.';
  end if;

  update public.discussion_sessions
  set status = case when status = 'waiting_for_missing_player' then 'voting' else status end,
      phase_deadline = greatest(coalesce(phase_deadline, now()), now())
        + make_interval(secs => p_seconds)
  where discussion_session_id = v_session.discussion_session_id
  returning * into v_session;

  perform public.s2_log_event(
    v_run.run_id, v_room_code, v_session.discussion_session_id,
    'teacher_added_time', null, jsonb_build_object('seconds', p_seconds)
  );

  return jsonb_build_object('status', v_session.status, 'phase_deadline', v_session.phase_deadline);
end;
$$;

create or replace function public.s2_send_message(
  p_room_code text,
  p_session_token text,
  p_message_text text
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_room_code text := upper(trim(p_room_code));
  v_player public.s1_room_players%rowtype;
  v_run public.game_runs%rowtype;
  v_session public.discussion_sessions%rowtype;
  v_message public.dialogue_messages%rowtype;
  v_text text := trim(coalesce(p_message_text, ''));
begin
  v_player := public.s1_get_player_by_session(v_room_code, p_session_token);
  v_run := public.s2_get_active_run(v_room_code);
  if v_run.run_id is null then raise exception 'No active formal run.'; end if;

  select * into v_session
  from public.discussion_sessions
  where run_id = v_run.run_id
  order by vote_round desc
  limit 1;

  if not found then raise exception 'No discussion has been opened.'; end if;
  perform public.s2_refresh_discussion(v_session.discussion_session_id);
  select * into v_session from public.discussion_sessions
  where discussion_session_id = v_session.discussion_session_id;

  if v_session.status <> 'discussion' or not v_session.allow_free_text then
    raise exception 'Free-text discussion is not currently open.';
  end if;
  if v_text = '' or char_length(v_text) > 1000 then
    raise exception 'Message must contain 1-1000 characters.';
  end if;

  insert into public.dialogue_messages(
    run_id, discussion_session_id, scene_id, phase_key, step_key,
    player_id, message_text
  ) values (
    v_run.run_id, v_session.discussion_session_id, v_session.scene_id,
    v_session.phase_key, v_session.step_key, v_player.player_id, v_text
  ) returning * into v_message;

  perform public.s2_log_event(
    v_run.run_id, v_room_code, v_session.discussion_session_id,
    'dialogue_message_sent', v_player.player_id,
    jsonb_build_object('message_id', v_message.message_id)
  );

  return jsonb_build_object(
    'message_id', v_message.message_id,
    'created_at', v_message.created_at
  );
end;
$$;

create or replace function public.s2_submit_vote(
  p_room_code text,
  p_session_token text,
  p_choice_id text
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_room_code text := upper(trim(p_room_code));
  v_player public.s1_room_players%rowtype;
  v_run public.game_runs%rowtype;
  v_session public.discussion_sessions%rowtype;
  v_new_session public.discussion_sessions%rowtype;
  v_choice_label text;
  v_vote_count integer;
  v_winner record;
  v_distinct integer;
  v_should_revote boolean := false;
begin
  v_player := public.s1_get_player_by_session(v_room_code, p_session_token);
  v_run := public.s2_get_active_run(v_room_code);
  if v_run.run_id is null then raise exception 'No active formal run.'; end if;

  select * into v_session
  from public.discussion_sessions
  where run_id = v_run.run_id
  order by vote_round desc
  limit 1
  for update;

  if not found then raise exception 'No discussion has been opened.'; end if;
  perform public.s2_refresh_discussion(v_session.discussion_session_id);
  select * into v_session from public.discussion_sessions
  where discussion_session_id = v_session.discussion_session_id
  for update;

  if v_session.status <> 'voting' then
    raise exception 'Voting is not currently open.';
  end if;

  select option_item->>'label' into v_choice_label
  from jsonb_array_elements(v_session.vote_options) option_item
  where option_item->>'id' = p_choice_id;

  if not found then raise exception 'Invalid vote option.'; end if;

  insert into public.runtime_player_decisions(
    run_id, discussion_session_id, scene_id, phase_key, step_key,
    vote_round, player_id, decision_type, choice_id, choice_label
  ) values (
    v_run.run_id, v_session.discussion_session_id, v_session.scene_id,
    v_session.phase_key, v_session.step_key, v_session.vote_round,
    v_player.player_id, 'group_vote', p_choice_id, v_choice_label
  );

  perform public.s2_log_event(
    v_run.run_id, v_room_code, v_session.discussion_session_id,
    'group_vote_locked', v_player.player_id,
    jsonb_build_object('vote_round', v_session.vote_round)
  );

  select count(*), count(distinct choice_id)
  into v_vote_count, v_distinct
  from public.runtime_player_decisions
  where discussion_session_id = v_session.discussion_session_id
    and decision_type = 'group_vote';

  if v_vote_count < 3 then
    return jsonb_build_object('ok', true, 'submitted_count', v_vote_count, 'status', 'voting');
  end if;

  select choice_id, choice_label, count(*)::integer as votes
  into v_winner
  from public.runtime_player_decisions
  where discussion_session_id = v_session.discussion_session_id
    and decision_type = 'group_vote'
  group by choice_id, choice_label
  order by count(*) desc, choice_id
  limit 1;

  if v_winner.votes >= 2 then
    update public.discussion_sessions
    set status = 'resolved', ended_at = now(), phase_deadline = null,
        outcome = jsonb_build_object(
          'type', 'majority', 'choice_id', v_winner.choice_id,
          'choice_label', v_winner.choice_label, 'votes', v_winner.votes,
          'vote_round', v_session.vote_round
        )
    where discussion_session_id = v_session.discussion_session_id;

    perform public.s2_log_event(
      v_run.run_id, v_room_code, v_session.discussion_session_id,
      'vote_resolved_majority', null,
      jsonb_build_object('choice_id', v_winner.choice_id, 'votes', v_winner.votes)
    );

    return jsonb_build_object(
      'ok', true, 'status', 'resolved', 'resolution', 'majority',
      'choice_id', v_winner.choice_id, 'votes', v_winner.votes
    );
  end if;

  -- With exactly three players, no majority means a 1:1:1 result.
  if v_distinct = 3 then
    update public.discussion_sessions
    set status = 'resolved', ended_at = now(), phase_deadline = null,
        outcome = jsonb_build_object(
          'type', 'no_consensus', 'message', 'NO CONSENSUS. NO ACTION.',
          'vote_round', v_session.vote_round
        )
    where discussion_session_id = v_session.discussion_session_id;

    perform public.s2_log_event(
      v_run.run_id, v_room_code, v_session.discussion_session_id,
      'vote_no_consensus', null,
      jsonb_build_object('vote_round', v_session.vote_round, 'action_applied', false)
    );

    v_should_revote := v_session.tie_policy = 'REPEAT_UNTIL_MAJORITY'
      or (
        v_session.tie_policy = 'SINGLE_REVOTE_THEN_FALLBACK'
        and v_session.round_no <= coalesce(v_session.max_revotes, 0)
      );

    if v_should_revote then
      insert into public.discussion_sessions(
        run_id, scene_id, phase_key, step_key, round_no, vote_round,
        topic, phase_deadline, show_initial_choices, require_final_vote,
        vote_options, tie_policy, revote_window_sec, max_revotes,
        fallback_resolution, discussion_time_limit_sec, vote_time_limit_sec,
        silent_texting_mode
      ) values (
        v_session.run_id, v_session.scene_id, v_session.phase_key, v_session.step_key,
        v_session.round_no + 1, v_session.vote_round + 1,
        v_session.topic,
        now() + make_interval(secs => coalesce(v_session.revote_window_sec, v_session.discussion_time_limit_sec)),
        v_session.show_initial_choices, v_session.require_final_vote,
        v_session.vote_options, v_session.tie_policy, v_session.revote_window_sec,
        v_session.max_revotes, v_session.fallback_resolution,
        v_session.discussion_time_limit_sec, v_session.vote_time_limit_sec,
        v_session.silent_texting_mode
      ) returning * into v_new_session;

      perform public.s2_log_event(
        v_run.run_id, v_room_code, v_new_session.discussion_session_id,
        'revote_discussion_opened', null,
        jsonb_build_object(
          'previous_discussion_session_id', v_session.discussion_session_id,
          'vote_round', v_new_session.vote_round
        )
      );

      return jsonb_build_object(
        'ok', true, 'status', 'discussion', 'resolution', 'no_consensus',
        'message', 'NO CONSENSUS. NO ACTION.',
        'discussion_session_id', v_new_session.discussion_session_id,
        'vote_round', v_new_session.vote_round
      );
    end if;

    if v_session.fallback_resolution is not null then
      update public.discussion_sessions
      set outcome = jsonb_build_object(
        'type', 'fallback',
        'resolution_id', v_session.fallback_resolution,
        'resolution_source', 'system_fallback',
        'after_no_consensus', true, 'vote_round', v_session.vote_round
      )
      where discussion_session_id = v_session.discussion_session_id;

      perform public.s2_log_event(
        v_run.run_id, v_room_code, v_session.discussion_session_id,
        'vote_resolved_fallback', null,
        jsonb_build_object(
          'resolution_id', v_session.fallback_resolution,
          'resolution_source', 'system_fallback'
        )
      );
    end if;

    return jsonb_build_object(
      'ok', true, 'status', 'resolved', 'resolution',
      case when v_session.fallback_resolution is null then 'no_consensus' else 'fallback' end,
      'resolution_id', v_session.fallback_resolution,
      'resolution_source', case when v_session.fallback_resolution is null then null else 'system_fallback' end
    );
  end if;

  raise exception 'Unexpected vote tally state.';
exception
  when unique_violation then
    raise exception 'Your vote for this vote round is already locked.';
end;
$$;

create or replace function public.s3_record_observation(
  p_run_id uuid, p_player_id uuid, p_observation_key text, p_scene_id text
) returns void
language plpgsql security definer set search_path = public as $$
declare v_text_key text;
begin
  select display_text_key into strict v_text_key
  from public.s3_observation_catalog where observation_key = p_observation_key;
  insert into public.s3_player_observations(
    run_id, player_id, observation_key, display_text_key, discovered_at_scene
  ) values (p_run_id, p_player_id, p_observation_key, v_text_key, p_scene_id)
  on conflict (run_id, player_id, observation_key) do nothing;
exception when no_data_found then raise exception 'Invalid observation identity.';
end;
$$;

create or replace function public.s3_get_teacher_state(p_room_code text,p_teacher_token text)
returns jsonb language plpgsql security definer set search_path=public as $$
declare v_room text:=upper(trim(p_room_code)); v_run public.game_runs%rowtype;
begin
  perform public.s1_assert_teacher(v_room,p_teacher_token); v_run:=public.s2_get_active_run(v_room);
  if v_run.run_id is null then return jsonb_build_object('active',false); end if;
  return jsonb_build_object('active',true,'run_id',v_run.run_id,'run_mode',v_run.run_mode,
    'scene',(select jsonb_build_object('scene_id',scene_id,'phase_key',phase_key,'step_key',step_key,'display_mode',display_mode,'text_key',text_key) from public.s3_runtime_scene_state where run_id=v_run.run_id),
    'counts',jsonb_build_object(
      'physical_items',(select count(*) from public.s3_player_items where run_id=v_run.run_id),
      'observations',(select count(*) from public.s3_player_observations where run_id=v_run.run_id),
      'shared_photos',(select count(*) from public.s3_shared_photos where run_id=v_run.run_id),
      'group_items',(select count(*) from public.s3_group_items where run_id=v_run.run_id),
      'knowledge_acquisitions',(select count(*) from public.s3_player_knowledge where run_id=v_run.run_id)));
end; $$;

create or replace function public.s3_record_knowledge(
  p_run_id uuid, p_player_id uuid, p_knowledge_key text, p_source text,
  p_scene_id text, p_source_player_id uuid default null, p_source_item_key text default null
) returns void
language plpgsql security definer set search_path=public as $$
declare v_room text; v_actual_sender uuid;
begin
  select room_code into v_room from public.game_runs where run_id=p_run_id;
  if v_room is null then raise exception 'Invalid run identity.'; end if;
  if not exists(select 1 from public.s1_room_players where player_id=p_player_id and room_code=v_room) then
    raise exception 'Knowledge holder does not belong to this run room.';
  end if;
  if p_source_player_id is not null and not exists(select 1 from public.s1_room_players where player_id=p_source_player_id and room_code=v_room) then
    raise exception 'Knowledge source player does not belong to this run room.';
  end if;
  if not exists(select 1 from public.s3_knowledge_catalog where knowledge_key=p_knowledge_key) then raise exception 'Invalid knowledge identity.'; end if;
  if p_source not in ('direct_observation','private_system_message','pocket_inspection','shared_photo','chat_from_player','group_item') then raise exception 'Invalid knowledge source.'; end if;

  if p_source in ('direct_observation','private_system_message') then
    if p_source_player_id is not null or p_source_item_key is not null then raise exception 'This knowledge source does not accept item or player provenance.'; end if;
  elsif p_source='chat_from_player' then
    if p_source_player_id is null or p_source_item_key is not null then raise exception 'chat_from_player requires only a valid source player.'; end if;
  elsif p_source='pocket_inspection' then
    if p_source_player_id is not null or not exists(select 1 from public.s3_player_items where run_id=p_run_id and physical_owner_id=p_player_id and item_key=p_source_item_key) then
      raise exception 'Pocket provenance requires an item physically owned by the holder.';
    end if;
  elsif p_source='shared_photo' then
    select shared_by into v_actual_sender from public.s3_shared_photos
    where run_id=p_run_id and received_by=p_player_id and source_item_key=p_source_item_key
    order by shared_at desc limit 1;
    if v_actual_sender is null then raise exception 'Shared-photo provenance requires an actual received copy.'; end if;
    if p_source_player_id is not null and p_source_player_id<>v_actual_sender then raise exception 'Shared-photo source player contradicts stored provenance.'; end if;
    p_source_player_id:=v_actual_sender;
  elsif p_source='group_item' then
    if p_source_player_id is not null or not exists(select 1 from public.s3_group_items where run_id=p_run_id and item_key=p_source_item_key) then
      raise exception 'Group-item provenance requires an item present in this run.';
    end if;
  end if;

  insert into public.s3_player_knowledge(run_id,player_id,knowledge_key,source,scene_id,source_player_id,source_item_key)
  values(p_run_id,p_player_id,p_knowledge_key,p_source,p_scene_id,p_source_player_id,p_source_item_key)
  on conflict do nothing;
end; $$;

create or replace function public.s3_initialize_audit_fixture(p_room_code text,p_teacher_token text)
returns jsonb language plpgsql security definer set search_path=public as $$
declare v_room text:=upper(trim(p_room_code)); v_run public.game_runs%rowtype; v_gitte uuid;
begin
  perform public.s1_assert_teacher(v_room,p_teacher_token); v_run:=public.s2_get_active_run(v_room);
  if v_run.run_id is null then raise exception 'No active formal run.'; end if;
  if v_run.run_mode<>'audit' then raise exception 'Sprint 3A fixture is restricted to AUDIT runs.'; end if;
  select player_id into strict v_gitte from public.s1_room_players where room_code=v_room and role_slot='GAL-A';
  insert into public.s3_runtime_scene_state(run_id,scene_id,phase_key,step_key,display_mode,text_key)
  values(v_run.run_id,'s3a-foundation-fixture','foundation','initial','ACTION_SCREEN','common.001') on conflict(run_id) do nothing;
  insert into public.s3_player_items(run_id,item_key,physical_owner_id) values(v_run.run_id,'fixture.physical_item',v_gitte) on conflict do nothing;
  insert into public.s3_player_item_view_state(run_id,player_id,item_key,current_view) values(v_run.run_id,v_gitte,'fixture.physical_item','front') on conflict do nothing;
  insert into public.s3_group_items(run_id,item_key,label_text_key) values(v_run.run_id,'fixture.group_item','common.005') on conflict do nothing;
  perform public.s3_record_observation(v_run.run_id,v_gitte,'fixture.private_observation','s3a-foundation-fixture');
  perform public.s3_record_knowledge(v_run.run_id,v_gitte,'fixture.direct_knowledge','direct_observation','s3a-foundation-fixture');
  perform public.s3_record_knowledge(v_run.run_id,v_gitte,'fixture.direct_knowledge','pocket_inspection','s3a-foundation-fixture',null,'fixture.physical_item');
  return jsonb_build_object('ok',true,'run_id',v_run.run_id);
end; $$;

create or replace function public.s3_audit_provenance_probe(p_room_code text,p_teacher_token text,p_case text)
returns void language plpgsql security definer set search_path=public as $$
declare v_room text:=upper(trim(p_room_code)); v_run public.game_runs%rowtype; v_holder uuid; v_foreign uuid;
begin
  perform public.s1_assert_teacher(v_room,p_teacher_token); v_run:=public.s2_get_active_run(v_room);
  if v_run.run_mode<>'audit' then raise exception 'Provenance probe is restricted to AUDIT runs.'; end if;
  select player_id into v_holder from public.s1_room_players where room_code=v_room and role_slot='GAL-A';
  select player_id into v_foreign from public.s1_room_players where room_code<>v_room limit 1;
  if p_case='outside_holder' then perform public.s3_record_knowledge(v_run.run_id,v_foreign,'fixture.direct_knowledge','direct_observation','probe');
  elsif p_case='unowned_item' then perform public.s3_record_knowledge(v_run.run_id,v_holder,'fixture.direct_knowledge','pocket_inspection','probe',null,'fixture.group_item');
  elsif p_case='missing_photo' then perform public.s3_record_knowledge(v_run.run_id,v_holder,'fixture.photo_knowledge','shared_photo','probe',null,'fixture.physical_item');
  elsif p_case='absent_group' then perform public.s3_record_knowledge(v_run.run_id,v_holder,'fixture.direct_knowledge','group_item','probe',null,'fixture.physical_item');
  elsif p_case='cross_room_source' then perform public.s3_record_knowledge(v_run.run_id,v_holder,'fixture.direct_knowledge','chat_from_player','probe',v_foreign,null);
  else raise exception 'Invalid provenance probe case.'; end if;
end; $$;

create or replace function public.s3b_audit_expire_puzzle(p_room_code text,p_teacher_token text)
returns jsonb language plpgsql security definer set search_path=public as $$
declare v_room text:=upper(trim(p_room_code)); v_run public.game_runs%rowtype;
begin
  perform public.s1_assert_teacher(v_room,p_teacher_token); v_run:=public.s2_get_active_run(v_room);
  if v_run.run_mode<>'audit' then raise exception 'Puzzle deadline probe is restricted to AUDIT runs.'; end if;
  update public.s3b_run_state set puzzle_deadline=now()-interval '1 second' where run_id=v_run.run_id and puzzle_resolved_at is null;
  perform public.s3b_refresh_puzzle(v_run.run_id);
  return jsonb_build_object('ok',true,'hint_stage',(select puzzle_hint_stage from public.s3b_run_state where run_id=v_run.run_id));
end; $$;

create or replace function public.s3b_lock_run_for_player_progress()
returns trigger
language plpgsql
security definer
set search_path=public
as $$
begin
  perform 1 from public.s3b_run_state where run_id=new.run_id for update;
  if not found then raise exception 'Sprint 3B run state is not initialized.'; end if;
  return new;
end;
$$;
